import pytest
from candidate import prime_fib


class TestPrimeFibNormalCases:
    def test_prime_fib_first_value(self):
        assert prime_fib(1) == 2

    def test_prime_fib_second_value(self):
        assert prime_fib(2) == 3

    def test_prime_fib_third_value(self):
        assert prime_fib(3) == 5

    def test_prime_fib_fourth_value(self):
        assert prime_fib(4) == 13

    def test_prime_fib_fifth_value(self):
        assert prime_fib(5) == 89

    def test_prime_fib_sixth_value(self):
        assert prime_fib(6) == 233

    def test_prime_fib_seventh_value(self):
        assert prime_fib(7) == 1597

    def test_prime_fib_eighth_value(self):
        assert prime_fib(8) == 28657


class TestPrimeFibBoundaryConditions:
    def test_prime_fib_minimum_valid_input(self):
        assert prime_fib(1) == 2

    def test_prime_fib_consecutive_results_are_distinct(self):
        results = [prime_fib(i) for i in range(1, 6)]
        assert len(set(results)) == len(results)

    def test_prime_fib_results_are_increasing(self):
        results = [prime_fib(i) for i in range(1, 6)]
        assert all(results[i] < results[i + 1] for i in range(len(results) - 1))

    def test_prime_fib_float_integer_value(self):
        assert prime_fib(1.0) == 2

    def test_prime_fib_result_is_int_type(self):
        assert isinstance(prime_fib(1), int)

    def test_prime_fib_result_is_prime(self):
        for n in range(1, 6):
            result = prime_fib(n)
            if result < 2:
                pytest.fail(f"{result} is not prime")
            for i in range(2, int(result**0.5) + 1):
                assert result % i != 0

    def test_prime_fib_result_is_fibonacci_number(self):
        for n in range(1, 6):
            result = prime_fib(n)
            a, b = 0, 1
            found = False
            for _ in range(50):
                if b == result:
                    found = True
                    break
                a, b = b, a + b
            assert found


class TestPrimeFibErrorCases:
    def test_prime_fib_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            prime_fib(None)

    def test_prime_fib_string_input_raises_type_error(self):
        with pytest.raises(TypeError):
            prime_fib("1")

    def test_prime_fib_list_input_raises_type_error(self):
        with pytest.raises(TypeError):
            prime_fib([1])

    def test_prime_fib_tuple_input_raises_type_error(self):
        with pytest.raises(TypeError):
            prime_fib((1,))

    def test_prime_fib_dict_input_raises_type_error(self):
        with pytest.raises(TypeError):
            prime_fib({})

    def test_prime_fib_boolean_input(self):
        assert prime_fib(True) == 2


class TestPrimeFibEdgeCases:
    def test_prime_fib_larger_n(self):
        assert prime_fib(9) == 514229

    def test_prime_fib_result_greater_than_input(self):
        for n in range(1, 8):
            assert prime_fib(n) > n

    def test_prime_fib_all_results_odd_except_first(self):
        assert prime_fib(1) == 2
        for n in range(2, 8):
            assert prime_fib(n) % 2 != 0

    def test_prime_fib_no_zero_result(self):
        for n in range(1, 6):
            assert prime_fib(n) != 0

    def test_prime_fib_no_one_result(self):
        for n in range(1, 6):
            assert prime_fib(n) != 1
